CREATE COLUMN TABLE "TEST_AP"."OWTA" ("AbsEntry" INTEGER CS_INT NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "PmntDate" LONGDATE CS_LONGDATE NOT NULL , "WTTypeId" INTEGER CS_INT NOT NULL , "AccmAmnt" DECIMAL(21,6) CS_FIXED, "AccmAmntFC" DECIMAL(21,6) CS_FIXED, "AccmAmntSC" DECIMAL(21,6) CS_FIXED, "BPLId" INTEGER CS_INT DEFAULT 0 NOT NULL , PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWTA_SECONDARY" ON "TEST_AP"."OWTA" ( "CardCode" ASC, "PmntDate" ASC, "WTTypeId" ASC, "BPLId" ASC )